const server=http.createServer(async(req,res)=>{const requestId=crypto.randomUUID();try{secureHeaders(res);res.setHeader('X-Request-Id',requestId);const url=new URL(req.url,'http://localhost');if(url.pathname.startsWith('/api/')){if(!rateLimit(req,res,url))return;if(req.method==='POST'&&url.pathname==='/api/billing/webhook')return await handleStripeWebhook(req,res);if(req.method==='POST'&&url.pathname==='/api/auth/company'){const input=await body(req),companyId=await companyIdForEmail(input.email);return json(res,200,{companyId:companyId||null})}const guestToken=(req.method==='GET'||req.method==='POST')?url.pathname.match(/^\/api\/guest\/([a-f0-9]{48})$/):null,database=guestToken?await guestRequestDatabase(req,url,guestToken[1]):await requestDatabase(req);if(!database)return json(res,404,{error:guestToken?'This guest link is invalid or expired':'Company workspace not found'});const companyId=String(database.db?.company?.id||JSON.parse(fs.readFileSync(database.file,'utf8')).company.id);return withTenantQueue(companyId,async()=>{database.db=freshestTenantSnapshot(database);const context={...database,pending:[],backup:null};const result=await dbContext.run(context,()=>api(req,res,url));if(isCredentialAttempt(req,url)&&res.statusCode===401)recordAuthFailure(req);await Promise.all(context.pending);return result})}let requested=decodeURIComponent(url.pathname==='/'?'/landing.html':url.pathname==='/app'?'/index.html':url.pathname==='/favicon.ico'?'/assets/pro-daily-link-logo.png':/^\/guest\/[a-f0-9]{48}$/.test(url.pathname)?'/guest.html':url.pathname);let file=path.resolve(ROOT,'.'+requested);if(!file.startsWith(ROOT)||!fs.existsSync(file)||fs.statSync(file).isDirectory()){res.writeHead(404);return res.end('Not found')}const extension=path.extname(file),mustRevalidate=['.html','.js','.css'].includes(extension);res.writeHead(200,{'Content-Type':MIME[extension]||'application/octet-stream','Cache-Control':mustRevalidate?'no-cache, no-store, must-revalidate':'public, max-age=3600'});fs.createReadStream(file).pipe(res)}catch(error){console.error(`[${requestId}]`,error);if(process.env.SENTRY_DSN)Sentry.withScope(scope=>{scope.setTag('request_id',requestId);scope.setTag('method',req.method);scope.setTag('route',String(req.url||'').split('?')[0]);Sentry.captureException(error)});json(res,error.statusCode||500,{error:error.statusCode===413?'Request is too large':error.statusCode===400?'Invalid request body':'Unexpected server error',requestId})}});
server.requestTimeout=30000;server.headersTimeout=15000;server.keepAliveTimeout=5000;
if(require.main===module) Promise.all([loadPrimaryCloud(),loadPlatformCloud()]).finally(()=>server.listen(PORT,()=>console.log(`Pro Daily Link running at http://localhost:${PORT}`)));
